            hindi: 'तीनों लोकों में सुन्दर, रण-कौशल में धीर, कमलनयन, रघुवंश के स्वामी, करुणा के स्वरूप और दया के सागर श्रीरामचन्द्र की मैं शरण लेता हूँ। मन के समान वेगशाली, वायु के समान तीव्र, जितेन्द्रिय, बुद्धिमानों में श्रेष्ठ, वायुपुत्र, वानर-समूह के मुख्य श्रीरामदूत हनुमान की मैं शरण लेता हूँ। "राम-राम" कहकर मधुर अक्षरों में कूजने वाले वाल्मीकि रूपी कोकिल की मैं वन्दना करता हूँ, जो कविता रूपी शाखा पर विराजमान हैं। आपत्तियों का हरण करने वाले, समस्त सम्पदाओं के दाता, लोकाभिराम श्रीराम को मैं बारम्बार नमस्कार करता हूँ। संसार-बीजों (जन्म-मरण) को भूनने वाला, सुख-सम्पदाओं को अर्जित करने वाला और यमदूतों को तर्जित करने वाला "राम-राम" का उच्चारण ही परम गर्जना है। राजाओं में श्रेष्ठ श्रीराम सदा विजयी होते हैं, मैं उन लक्ष्मीनिकेतन श्रीराम को भजता हूँ। श्रीराम से बढ़कर कोई अन्य आश्रय नहीं, मैं श्रीराम का दास हूँ; मेरा चित्त सदा श्रीराम में लीन रहे, हे राम! मेरा उद्धार कीजिए। भगवान शिव माता पार्वती से कहते हैं: "श्रीराम" नाम का जप सहस्र विष्णु-नामों के तुल्य फल देने वाला है।',
