            hindi: 'हे राघव! आपत्तियों, कष्टों, भयानक वनों और भय में इस स्तोत्र का कीर्तन करने वाला कोई भी पुरुष कभी खिन्न नहीं होता। एकाग्र होकर इस देवदेव, जगत्पति की पूजा करो; इसका तीन गुना जप करके तुम युद्धों में विजय प्राप्त करोगे। हे महाबाहो! इसी क्षण तुम रावण का वध करोगे। ऐसा कहकर महर्षि अगस्त्य जैसे आए थे वैसे ही चले गए। यह सुनकर महातेजस्वी श्रीराम का शोक नष्ट हो गया और अत्यन्त प्रसन्न होकर उन्होंने इसे धारण किया। सूर्य को देखकर और इसका जप करके श्रीराम परम हर्ष को प्राप्त हुए; तीन बार आचमन करके पवित्र होकर उन्होंने धनुष उठाया। रावण को देखकर प्रसन्न मन से वे युद्ध के लिए आगे बढ़े और पूरे प्रयत्न से उसके वध में तत्पर हो गए। तब सूर्यदेव ने प्रसन्न मन से श्रीराम की ओर देखते हुए, राक्षसों के स्वामी का विनाश जानकर, देवगणों के मध्य "शीघ्र करो" — ऐसा कहा।',
